_editLog": [{"timestamp": "2026-07-02T05:26:18Z", "editorId": "gemini-2.5-flash·cloud·GH#28567519909", "field": "summary", "oldValue": "William de Bohun, 1st Earl of Northampton, KG was an English nobleman and military commander.", "newValue": "William de Bohun, 1st Earl of Northampton, a grandson of Edward I, emerged as a preeminent English military commander and diplomat during the early phases of the Hundred Years' War. Born into one of England's most powerful baronial families, his strategic acumen and martial prowess were instrumental in several pivotal English victories against France and Scotland. Elevated to the earldom of Northampton in 1337, he quickly became a trusted confidant and lieutenant of King Edward III, embodying the aristocratic martial culture of 14th-century England.

His military career was distinguished by critical engagements, most notably at the Battle of Crécy in 1346, where he commanded the second English division alongside the Earl of Arundel, contributing significantly to the devastating English longbow victory. Prior to this, he played a crucial role in the Battle of Sluys in 1340, a decisive naval engagement that established English supremacy in the English Channel. De Bohun also served as King's Lieutenant in Brittany from 1342, consolidating English interests during the War of the Breton Succession, and was a founding Knight of the Garter in 1348, a testament to his high standing and chivalric reputation within the English court.

De Bohun's influence extended beyond the battlefield into diplomacy, as he frequently represented Edward III in negotiations with France, Scotland, and the Holy Roman Empire, seeking alliances and mediating disputes. His wealth, extensive landholdings, and royal connections solidified his family's position as a linchpin of English aristocratic power, contributing to the stability of Edward III's war efforts. His actions helped shape the strategic direction of the Hundred Years' War in its formative decades, laying the groundwork for subsequent English successes and entrenching the Anglo-French conflict for generations."}, {"timestamp": "2026-07-02T05:26:18Z", "editorId": "gemini-2.5-flash·cloud·GH#28567519909", "field": "detailsJson.causes", "oldValue": [{"title": "Medieval era: interplay of religious authority, feudal governance, and trade network expansion", "type": "EventWindow", "year": "1312"}, {"title": "Political crises and power transitions requiring new leadership", "type": "Idea", "year": "1312"}], "newValue": ["The ongoing Hundred Years' War created a constant demand for skilled military commanders and loyal noblemen in service to the English Crown.", "His direct lineage to King Edward I and familial ties to powerful English baronial houses provided him with significant influence and opportunities for advancement.", "King Edward III's policy of elevating loyal and capable military leaders to earldoms and high offices ensured figures like de Bohun rose rapidly through the ranks."]}, {"timestamp": "2026-07-02T05:26:18Z", "editorId": "gemini-2.5-flash·cloud·GH#28567519909", "field": "detailsJson.effects", "oldValue": [{"title": "Shaped political institutions and governance practices", "type": "Idea", "year": "1360-09-24"}, {"title": "Contributed to synthesis of classical and religious thought informing Renaissance and Reformati", "type": "Movement", "year": "1360-09-24"}], "newValue": ["William de Bohun's military successes at Sluys and Crécy contributed sig